using UnityEngine;

public static class SpiritEffects {
 public static Mesh Quad(){var m=new Mesh{name="RuntimeEffectQuad"};m.vertices=new[]{new Vector3(-.5f,-.5f),new Vector3(.5f,-.5f),new Vector3(-.5f,.5f),new Vector3(.5f,.5f)};m.uv=new[]{Vector2.zero,Vector2.right,Vector2.up,Vector2.one};m.triangles=new[]{0,2,1,1,2,3};m.RecalculateBounds();return m;}
 public static Renderer Halo(string name,Transform parent,Vector3 pos,Vector2 size,Color color){var go=new GameObject(name);go.transform.SetParent(parent,false);go.transform.localPosition=pos;go.transform.localScale=new Vector3(size.x,size.y,1);go.AddComponent<MeshFilter>().sharedMesh=Quad();var r=go.AddComponent<MeshRenderer>();var m=new Material(Shader.Find("LightFeast/SoftLight"));m.SetFloat("_Radial",1);m.SetColor("_Color",color);r.sharedMaterial=m;return r;}
 public static ParticleSystem Embers(Transform parent){var go=new GameObject("Hair_LightSparks");go.transform.SetParent(parent,false);go.transform.localPosition=new Vector3(-.15f,.85f,-.1f);var p=go.AddComponent<ParticleSystem>();p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=p.main;main.startLifetime=.8f;main.startSpeed=.18f;main.startSize=new ParticleSystem.MinMaxCurve(.02f,.06f);main.startColor=new Color(1,.8f,.35f,.7f);main.simulationSpace=ParticleSystemSimulationSpace.World;main.maxParticles=64;var e=p.emission;e.rateOverTime=7;var shape=p.shape;shape.shapeType=ParticleSystemShapeType.Sphere;shape.radius=.1f;var c=p.colorOverLifetime;c.enabled=true;var g=new Gradient();g.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(new Color(1,.7f,.2f),1)},new[]{new GradientAlphaKey(.8f,0),new GradientAlphaKey(0,1)});c.color=g;var r=p.GetComponent<ParticleSystemRenderer>();r.sharedMaterial=new Material(Shader.Find("LightFeast/SoftLight"));r.sharedMaterial.SetFloat("_Radial",1);p.Play();return p;}
}
